export const API_DOCS_HTML = "<!doctype html>\n<html lang=\"en\"><head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>BeamTerminal API</title>\n<style>\n/* Match the site's webfont (served as static by nginx at /assets/fonts). */\n@font-face{font-family:'ProximaNova';font-weight:400;font-display:swap;src:url('https://beamterminal.0xmx.net/assets/fonts/ProximaNova-Regular.woff') format('woff')}\n@font-face{font-family:'ProximaNova';font-weight:600;font-display:swap;src:url('https://beamterminal.0xmx.net/assets/fonts/ProximaNova-Semibold.woff') format('woff')}\n@font-face{font-family:'ProximaNova';font-weight:700;font-display:swap;src:url('https://beamterminal.0xmx.net/assets/fonts/ProximaNova-Bold.woff') format('woff')}\n:root{--bg:#042548;--surface:rgba(255,255,255,.04);--border:rgba(255,255,255,.12);--text:#e8f0f7;--muted:rgba(232,240,247,.6);--accent:#00f6d2;--link:#4f9dff}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--text);font:14px/1.6 'ProximaNova','SFProDisplay',sans-serif}\na{color:var(--link);text-decoration:none}a:hover{text-decoration:underline}\n.wrap{display:grid;grid-template-columns:260px 1fr;gap:24px;max-width:1200px;margin:0 auto;padding:24px}\n.sidebar{position:sticky;top:24px;align-self:start;max-height:calc(100vh - 48px);overflow:auto;border-right:1px solid var(--border);padding-right:12px}\n.toc-group{margin-bottom:18px}\n.toc-title{font-weight:700;color:var(--accent);text-transform:uppercase;font-size:11px;letter-spacing:.05em;margin-bottom:6px}\n.sidebar a{display:block;padding:2px 0;color:var(--muted);font-size:13px}\n.sidebar a.toc-l3{padding-left:12px;font-size:12px}\n.sidebar a:hover{color:var(--text)}\n.content{min-width:0}\n.content h1{color:var(--accent)} .content h2{border-top:1px solid var(--border);padding-top:18px;margin-top:28px}\n.content code{background:var(--surface);padding:2px 5px;border-radius:4px;font-family:ui-monospace,Menlo,monospace;font-size:12.5px}\n.content pre{background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:12px;overflow:auto}\n.content pre code{background:none;padding:0}\n.content table{border-collapse:collapse;width:100%;margin:12px 0}\n.content th,.content td{border:1px solid var(--border);padding:6px 10px;text-align:left}\n.content th{background:var(--surface)}\n@media(max-width:820px){.wrap{grid-template-columns:1fr}.sidebar{position:static;max-height:none;border-right:none;border-bottom:1px solid var(--border);padding-bottom:12px}}\n.site-footer{border-top:1px solid var(--border)}\n.site-footer-inner{max-width:1200px;margin:0 auto;padding:24px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px}\n.site-footer .fcol-title{font-weight:700;color:var(--accent);text-transform:uppercase;font-size:11px;letter-spacing:.05em;margin-bottom:8px}\n.site-footer a{display:block;color:var(--muted);font-size:13px;padding:2px 0}\n.site-footer a:hover{color:var(--text)}\n@media(max-width:820px){.site-footer-inner{grid-template-columns:1fr 1fr}}\n</style></head>\n<body><div class=\"wrap\">\n<nav class=\"sidebar\"><div class=\"toc-group\"><div class=\"toc-title\">Internal /api</div><a class=\"toc-l2\" href=\"#api-conventions\">Conventions</a><a class=\"toc-l2\" href=\"#api-get-api-health\">GET /api/health</a><a class=\"toc-l2\" href=\"#api-get-api-stats\">GET /api/stats</a><a class=\"toc-l2\" href=\"#api-get-api-pairs\">GET /api/pairs</a><a class=\"toc-l3\" href=\"#api-grouped-mode-group-pair\">Grouped mode (group=pair)</a><a class=\"toc-l3\" href=\"#api-sort-routing\">Sort routing</a><a class=\"toc-l2\" href=\"#api-get-api-pairs-id\">GET /api/pairs/{id}</a><a class=\"toc-l2\" href=\"#api-get-api-lp-position-deposit\">GET /api/lp-position/deposit</a><a class=\"toc-l2\" href=\"#api-get-api-lp-position-events\">GET /api/lp-position/events</a><a class=\"toc-l2\" href=\"#api-get-api-pairs-id-ohlcv\">GET /api/pairs/{id}/ohlcv</a><a class=\"toc-l2\" href=\"#api-get-api-pairs-id-trades\">GET /api/pairs/{id}/trades</a><a class=\"toc-l2\" href=\"#api-get-api-pairs-id-liquidity\">GET /api/pairs/{id}/liquidity</a><a class=\"toc-l2\" href=\"#api-get-api-assets\">GET /api/assets</a><a class=\"toc-l2\" href=\"#api-get-api-asset-aid\">GET /api/asset/{aid}</a><a class=\"toc-l2\" href=\"#api-get-api-asset-aid-history\">GET /api/asset/{aid}/history</a><a class=\"toc-l2\" href=\"#api-get-api-asset-aid-distribution\">GET /api/asset/{aid}/distribution</a><a class=\"toc-l2\" href=\"#api-get-api-network\">GET /api/network</a><a class=\"toc-l2\" href=\"#api-get-api-mining-pools\">GET /api/mining/pools</a><a class=\"toc-l2\" href=\"#api-get-api-mining-blocks\">GET /api/mining/blocks</a><a class=\"toc-l2\" href=\"#api-get-api-charts-series\">GET /api/charts/{series}</a><a class=\"toc-l3\" href=\"#api-query-params\">Query params</a><a class=\"toc-l2\" href=\"#api-get-api-bans-actions\">GET /api/bans/actions</a><a class=\"toc-l2\" href=\"#api-get-api-bridge-health\">GET /api/bridge/health</a><a class=\"toc-l2\" href=\"#api-get-api-bridge-lookup\">GET /api/bridge/lookup</a><a class=\"toc-l2\" href=\"#api-get-api-bridge-messages\">GET /api/bridge/messages</a><a class=\"toc-l2\" href=\"#api-quote-endpoint-intentionally-not-present\">Quote endpoint — intentionally not present</a><a class=\"toc-l2\" href=\"#api-usd-valuation\">USD valuation</a><a class=\"toc-l2\" href=\"#api-freshness-model\">Freshness model</a><a class=\"toc-l2\" href=\"#api-response-time-targets\">Response-time targets</a><a class=\"toc-l2\" href=\"#api-versioning\">Versioning</a></div><div class=\"toc-group\"><div class=\"toc-title\">CoinGecko /cg</div><a class=\"toc-l2\" href=\"#cg-general-requirements\">General requirements</a><a class=\"toc-l2\" href=\"#cg-pair-identity-mapping-beam-cg\">Pair identity mapping (BEAM → CG)</a><a class=\"toc-l2\" href=\"#cg-endpoint-1-get-cg-tickers\">Endpoint 1 — GET /cg/tickers</a><a class=\"toc-l3\" href=\"#cg-per-field-semantics\">Per-field semantics</a><a class=\"toc-l3\" href=\"#cg-pools-we-omit\">Pools we omit</a><a class=\"toc-l2\" href=\"#cg-endpoint-2-get-cg-historical-trades-ticker-id\">Endpoint 2 — GET /cg/historical_trades/{ticker_id}</a><a class=\"toc-l3\" href=\"#cg-per-field-semantics-x\">Per-field semantics</a><a class=\"toc-l2\" href=\"#cg-orderbook-policy\">Orderbook policy</a><a class=\"toc-l2\" href=\"#cg-what-cg-verifies-on-submission\">What CG verifies on submission</a><a class=\"toc-l2\" href=\"#cg-submission-checklist\">Submission checklist</a><a class=\"toc-l2\" href=\"#cg-implementation-notes\">Implementation notes</a><a class=\"toc-l2\" href=\"#cg-reference-implementations-cited-by-the-spec\">Reference implementations cited by the spec</a></div></nav>\n<main class=\"content\">\n<h1>BeamTerminal API</h1>\n<p class=\"muted\">Read-only reference, generated from <code>docs/api.md</code> and <code>docs/CoinGecko.md</code>. All endpoints are open, GET-only. Base URL: <code>https://beamterminal.0xmx.net</code>.</p>\n<h1>Internal API (<code>/api/*</code>)</h1>\n<p>UI-facing REST. Stateless Fastify service (<code>backend/src/api.ts</code>). Reads from Postgres only.</p>\n<p>The public CoinGecko-compliant endpoints (<code>/cg/*</code>) are documented separately in <a href=\"CoinGecko.md\">CoinGecko.md</a>.</p>\n<blockquote>\n<p>The human-readable version of this file is served at <code>/api</code>, generated by <code>backend/scripts/gen-api-docs.mjs</code>.</p>\n</blockquote>\n<h2 id=\"api-conventions\">Conventions</h2>\n<ul>\n<li><strong>Transport</strong>: JSON, UTF-8, <code>application/json; charset=utf-8</code>. Only <code>GET</code> is exposed.</li>\n<li><strong>Numbers</strong>: amounts in groths are returned as <strong>strings</strong> (<code>NUMERIC(40, 0)</code> doesn&#39;t fit in JS <code>number</code>). The frontend divides by <code>10^decimals</code> to display. USD numbers are JSON numbers (USD never overflows). Timestamps are unix seconds (number); heights are integers.</li>\n<li><strong>Errors</strong>:<pre><code class=\"language-json\">{ &quot;error&quot;: { &quot;code&quot;: &quot;PAIR_NOT_FOUND&quot;, &quot;message&quot;: &quot;no pair 0-31-1&quot; } }\n</code></pre>\n<code>code</code> is stable; <code>message</code> is human-readable and may change.</li>\n<li><strong>Auth</strong>: none.</li>\n<li><strong>CORS</strong>: open (<code>Access-Control-Allow-Origin: *</code>). The in-wallet origin works the same way.</li>\n<li><strong>Rate limit</strong>: per-IP via <code>@fastify/rate-limit</code>, <code>RATE_LIMIT_PER_MIN</code> (default 600/min). Set to 0 to disable. Excess responses are <code>{ &quot;error&quot;: { &quot;code&quot;: &quot;RATE_LIMITED&quot;, &quot;message&quot;: &quot;…&quot; } }</code>.</li>\n<li><strong>Cache-Control</strong>: per-route, typically <code>public, max-age=15</code> or <code>30</code>. <code>/api/health</code> is <code>no-store</code>.</li>\n<li><strong>API base in production</strong>: <code>https://beamterminal.0xmx.net/api</code>. The frontend hard-codes this in <code>frontend/src/app/containers/Screener/api/client.ts</code>.</li>\n</ul>\n<h2 id=\"api-get-api-health\"><code>GET /api/health</code></h2>\n<p>Liveness. Returns 200 with the lag between <code>now()</code> and <code>cursor.updated_at</code>. 503 if the cursor row is missing.</p>\n<pre><code class=\"language-json\">{\n  &quot;status&quot;: &quot;ok&quot;,\n  &quot;last_indexed_height&quot;: 3863512,\n  &quot;lag_seconds&quot;: 14\n}\n</code></pre>\n<p><code>Cache-Control: no-store</code>. The indexer rate-limit applies but <code>/api/health</code> is logged at debug level only (so it doesn&#39;t drown the request log if a probe hits it every second).</p>\n<h2 id=\"api-get-api-stats\"><code>GET /api/stats</code></h2>\n<p>Header strip data: BEAM/USD, total TVL, 24h volume, lifetime volume, pair/trade counts.</p>\n<pre><code class=\"language-json\">{\n  &quot;beam_usd&quot;: 0.02175,\n  &quot;total_tvl_usd&quot;: 124501.22,\n  &quot;volume_24h_usd&quot;: 9182.04,\n  &quot;total_volume_usd&quot;: 4521903.55,\n  &quot;total_pairs&quot;: 95,\n  &quot;total_trades&quot;: 41812,\n  &quot;last_indexed_height&quot;: 3863512,\n  &quot;block_ts&quot;: 1747400940\n}\n</code></pre>\n<ul>\n<li><code>total_tvl_usd</code> — sums <code>reserve1_usd + reserve2_usd</code> per active pool. For pools where only one side has a USD rate (via the <a href=\"database.md#usd-valuation-strategy\">USD valuation routing</a>), the known side is doubled (AMMs hold equal value on both sides at equilibrium). Pools where neither side is priceable are skipped.</li>\n<li><code>volume_24h_usd</code> — sums one priced side per pool over the 24h trade window.</li>\n<li><code>total_volume_usd</code> — point-in-time-valued lifetime volume, served from the precomputed <code>dex_stats</code> cache (refreshed by the indexer every 5 minutes). <code>null</code> until the first refresh after a fresh deploy.</li>\n<li><code>block_ts</code> — timestamp of the latest oracle snapshot (proxy for last-tick wall-clock time).</li>\n</ul>\n<p><code>Cache-Control: public, max-age=15</code>.</p>\n<h2 id=\"api-get-api-pairs\"><code>GET /api/pairs</code></h2>\n<p>List of all pairs with 24h stats baked in.</p>\n<p>Query params:</p>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Default</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>sort_by</code></td>\n<td><code>tvl_usd | volume_24h_usd | price_change_24h | trades_24h | aid2</code></td>\n<td><code>tvl_usd</code></td>\n<td></td>\n</tr>\n<tr>\n<td><code>order</code></td>\n<td><code>asc | desc</code></td>\n<td><code>desc</code></td>\n<td></td>\n</tr>\n<tr>\n<td><code>limit</code></td>\n<td>int, 1..500</td>\n<td>100</td>\n<td></td>\n</tr>\n<tr>\n<td><code>offset</code></td>\n<td>int</td>\n<td>0</td>\n<td></td>\n</tr>\n<tr>\n<td><code>search</code></td>\n<td>string</td>\n<td>—</td>\n<td>Substring match on <code>short_name</code> or exact AID. Splits on <code>/</code> so <code>BEAM/USDT</code> narrows to both sides.</td>\n</tr>\n<tr>\n<td><code>kind</code></td>\n<td><code>0 | 1 | 2</code></td>\n<td>—</td>\n<td>Filter to one volatility tier.</td>\n</tr>\n<tr>\n<td><code>include_imposters</code></td>\n<td>bool</td>\n<td>false</td>\n<td>If true, includes pools where either side has <code>is_imposter = TRUE</code>.</td>\n</tr>\n<tr>\n<td><code>group</code></td>\n<td><code>tier | pair</code></td>\n<td><code>tier</code></td>\n<td><code>pair</code> collapses fee tiers into one combined row per <code>(aid1, aid2)</code>.</td>\n</tr>\n</tbody></table>\n<h3 id=\"api-grouped-mode-group-pair\">Grouped mode (<code>group=pair</code>)</h3>\n<p>The screener lists each pair once instead of once per fee tier. Reserves,\n<code>volume_24h_*</code>, <code>trades_24h</code>/<code>buys_24h</code>/<code>sells_24h</code> and <code>tvl_usd</code> are <strong>summed</strong>\nacross tiers; <code>price_native</code>/<code>price_usd</code>/<code>price_change_24h</code>/<code>sparkline_7d</code> and\nthe identity fields (<code>pair_id</code>, <code>kind</code>, <code>lp_token</code>) come from the <strong>reference\n(deepest) tier</strong> — the pool with the largest <code>reserve1</code>, matching the\nUSD-valuation convention. Each grouped row adds a <code>tiers[]</code> array (one entry per\nfee tier, deepest first) carrying <code>{ pool_id, kind, kind_label, lp_token, tvl_usd, volume_24h_usd, reserve1_human, reserve2_human, price_native }</code>. Sorting\nand slicing happen app-side after the merge.</p>\n<p>Response shape (one entry shown — see <code>frontend/src/app/containers/Screener/api/types.ts</code> for the canonical TS type):</p>\n<pre><code class=\"language-json\">{\n  &quot;pairs&quot;: [\n    {\n      &quot;pair_id&quot;: 17,\n      &quot;aid1&quot;: 0, &quot;aid2&quot;: 31,\n      &quot;symbol1&quot;: &quot;BEAM&quot;, &quot;symbol2&quot;: &quot;USDT&quot;,\n      &quot;kind&quot;: 1, &quot;kind_label&quot;: &quot;Medium&quot;,\n      &quot;decimals1&quot;: 8, &quot;decimals2&quot;: 8,\n\n      &quot;price_native&quot;: 29.34293421,         // aid2 per 1 aid1\n      &quot;price_usd&quot;:    0.99,                // USD per 1 aid2 unit\n      &quot;rate_2_1&quot;:     0.03408871,          // 1 / price_native\n\n      &quot;reserve1&quot;:       &quot;12000000000000&quot;,  // groths\n      &quot;reserve2&quot;:       &quot;352115210340000&quot;,\n      &quot;reserve1_human&quot;: 120000.0,          // divided by 10^decimals\n      &quot;reserve2_human&quot;: 3521152.1,\n      &quot;reserve1_usd&quot;:   4092.00,\n      &quot;reserve2_usd&quot;:   3521152.10,\n      &quot;tvl_usd&quot;:        7613152.10,\n\n      &quot;volume_24h_groth&quot;: &quot;94000000000&quot;,\n      &quot;volume_24h_usd&quot;:   3206.84,\n\n      &quot;price_change_24h&quot;: 4.91,            // percent\n\n      &quot;buys_24h&quot;:  18,\n      &quot;sells_24h&quot;: 22,\n      &quot;trades_24h&quot;: 40,\n\n      &quot;is_imposter&quot;: false,\n      &quot;lp_token&quot;: 12345,                   // pools.aid_ctl\n      &quot;created_at_height&quot;: 1234567\n    }\n  ],\n  &quot;total&quot;: 95,\n  &quot;last_indexed_height&quot;: 3863512\n}\n</code></pre>\n<h3 id=\"api-sort-routing\">Sort routing</h3>\n<p><code>tvl_usd</code> and <code>volume_24h_usd</code> are computed app-side from the USD-per-AID rates (which come from the multi-hop helper, not SQL). When sorted by either, the handler pulls a default-ordered window of up to 500 rows, sorts in JS, and slices to <code>[offset, offset+limit]</code>. Other sort keys go straight to SQL.</p>\n<p>This matters because a tiny pool with huge raw-groth reserves but only ~$37 of USD value would otherwise rank above genuinely deep pools.</p>\n<p><code>Cache-Control: public, max-age=15</code>.</p>\n<h2 id=\"api-get-api-pairs-id\"><code>GET /api/pairs/{id}</code></h2>\n<p>Single pair, same fields as a row in <code>/api/pairs</code>.</p>\n<p><code>id</code> is one of:</p>\n<ul>\n<li>A numeric LP-token aid (<code>/api/pairs/12345</code>) — a single tier.</li>\n<li>A canonical tier tuple <code>&lt;aid1&gt;_&lt;aid2&gt;_&lt;kind&gt;</code> (<code>/api/pairs/0_31_1</code>; legacy <code>-</code>\nseparators also accepted) — a single tier, stable across DB recreations and\nsuitable for bookmarkable URLs.</li>\n<li>A <strong>combined-pair</strong> tuple <code>&lt;aid1&gt;_&lt;aid2&gt;</code> (<code>/api/pairs/0_31</code>) — returns the\ngrouped row across all fee tiers (summed stats + <code>tiers[]</code>, reference-tier\nprice), the same shape as a <code>group=pair</code> list entry.</li>\n</ul>\n<p>404 (<code>PAIR_NOT_FOUND</code>) when no matching pool exists.</p>\n<p>The row also carries <code>ctl_supply</code> (total LP-token supply, groths) and\n<code>snapshot_height</code> (the height the reserves/<code>ctl_supply</code> are from) — these power\nthe liquidity-position analyzer.</p>\n<p><code>Cache-Control: public, max-age=15</code>.</p>\n<h2 id=\"api-get-api-lp-position-deposit\"><code>GET /api/lp-position/deposit</code></h2>\n<p>Resolves a single <em>Liquidity Add</em> deposit so the frontend can analyse a\nliquidity position (share, fees, P&amp;L, impermanent loss — all computed\nclient-side from this plus <code>/api/pairs/{id}</code>). Exactly one query param:</p>\n<ul>\n<li><code>height=&lt;n&gt;</code> — looked up in <code>lp_events</code> (Postgres only).</li>\n<li><code>kernel=&lt;64 hex&gt;</code> — <strong>the one endpoint that touches the explorer</strong>: a single\n<code>/block?kernel=</code> call maps the kernel to its block height, then the same\n<code>lp_events</code> lookup runs. We don&#39;t index kernel ids, hence the hop.</li>\n</ul>\n<p>Returns a deposit object (<code>lp_token</code>, <code>aid1/aid2</code>, symbols, decimals, <code>kind</code> +\n<code>fee_pct</code>, <code>amount1/amount2/amount_ctl</code> in groths, <code>height</code>, <code>ts</code>, <code>confirmed</code>).\nWhen a height holds several deposits, returns <code>{ &quot;candidates&quot;: [ … ] }</code> for the\nUI to disambiguate. 404 (<code>DEPOSIT_NOT_FOUND</code> / <code>KERNEL_NOT_FOUND</code>) when nothing\nmatches.</p>\n<p><code>Cache-Control: public, max-age=30</code>.</p>\n<h2 id=\"api-get-api-lp-position-events\"><code>GET /api/lp-position/events</code></h2>\n<p>Multi-operation lookup powering the liquidity-position analyzer: resolves every\nadd/remove liquidity op across a list of references, so a position with several\ndeposits and partial withdrawals can be valued. One query param:</p>\n<ul>\n<li><code>refs=&lt;…&gt;</code> — up to 50 block heights and/or 64-hex kernel ids, comma/space/\nnewline separated. Kernel ids are resolved to heights via the explorer (the\nonly explorer touch); refs that don&#39;t resolve — or that exceed the 50 cap —\ncome back in <code>unresolved</code>.</li>\n</ul>\n<p>Returns <code>{ &quot;pools&quot;: [ … ], &quot;unresolved&quot;: [ … ] }</code>, with ops grouped <strong>by pool</strong>\n(<code>lp_token</code>). Each pool carries its asset/fee metadata, present-time per-unit\nBEAM/USD prices (<code>current_beam_per_aid1</code>, <code>current_usd_per_aid1</code>, …), and an\n<code>events[]</code> list; each event has <code>kind</code> (Deposit/Withdraw), <code>amount1/2/ctl</code>,\n<code>height</code>, <code>ts</code>, <code>confirmed</code>, and the <strong>historical</strong> BEAM/USD price of each asset\nat that op&#39;s height (<code>beam_per_aid1</code>, <code>usd_per_aid2</code>, … — null when the pair has\nno BEAM route). All P&amp;L / share / partial-withdrawal accounting is computed\nclient-side from this plus <code>/api/pairs/{id}</code>.</p>\n<p><code>Cache-Control: public, max-age=30</code>.</p>\n<h2 id=\"api-get-api-pairs-id-ohlcv\"><code>GET /api/pairs/{id}/ohlcv</code></h2>\n<p>Chart candles. Accepts any <code>id</code> form from <code>/api/pairs/{id}</code>. For a <strong>combined\npair</strong> (<code>&lt;aid1&gt;_&lt;aid2&gt;</code>) the price OHLC is taken from the reference (deepest)\ntier while <code>volume</code>/<code>trade_count</code> are <strong>summed across all tiers</strong> over the\nreference tier&#39;s bucket window. (Buckets where only a thinner tier traded — and\nthe reference tier did not — are not drawn.) Single-tier ids return that pool&#39;s\nseries unchanged.</p>\n<p>Query params:</p>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Default</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>interval</code></td>\n<td><code>1m | 5m | 15m | 1h | 4h | 1d</code></td>\n<td><code>1h</code></td>\n<td></td>\n</tr>\n<tr>\n<td><code>limit</code></td>\n<td>int, 1..2000</td>\n<td>500</td>\n<td></td>\n</tr>\n<tr>\n<td><code>to</code></td>\n<td>int (unix seconds)</td>\n<td><code>now</code></td>\n<td>Returns <code>limit</code> candles strictly older than <code>to</code>. Cursor for scroll-back.</td>\n</tr>\n<tr>\n<td><code>denom</code></td>\n<td><code>native | usd</code></td>\n<td><code>native</code></td>\n<td>If <code>usd</code>, OHLC values are converted using BEAM/USD valid at each candle&#39;s bucket. Only meaningful when one side of the pair is BEAM (aid 0).</td>\n</tr>\n</tbody></table>\n<p>Response:</p>\n<pre><code class=\"language-json\">{\n  &quot;candles&quot;: [\n    {\n      &quot;time&quot;: 1747400940,\n      &quot;open&quot;: 29.341, &quot;high&quot;: 29.401, &quot;low&quot;: 29.305, &quot;close&quot;: 29.380,\n      &quot;volume&quot;: &quot;9400000000&quot;,      // groths of aid1, string\n      &quot;trade_count&quot;: 7\n    }\n  ],\n  &quot;interval&quot;: &quot;1h&quot;,\n  &quot;denom&quot;: &quot;native&quot;,\n  &quot;more&quot;: { &quot;to&quot;: 1747314540 }    // cursor for the next older page, or null when exhausted\n}\n</code></pre>\n<p>USD conversion details:</p>\n<ul>\n<li>For a pool with <code>aid1 = 0 = BEAM</code>: native price is aid2-per-BEAM, so USD-per-aid2 = <code>beamUsd / native_price</code>. The route inverts high/low after conversion since the inversion swaps extremes.</li>\n<li>For <code>aid2 = 0</code>: USD-per-aid1 = <code>native_price * beamUsd</code> directly.</li>\n<li>For pools with no BEAM side: <code>denom=usd</code> silently falls back to native — the route can&#39;t construct a USD reference without an oracle path.</li>\n<li>The handler binary-searches per candle into the oracle history fetched for the candle window; for candles older than oracle history (e.g. backfilled trades pre-dating our deployment), it falls back to the most recent oracle snapshot.</li>\n</ul>\n<p><code>Cache-Control: public, max-age=30</code>.</p>\n<h2 id=\"api-get-api-pairs-id-trades\"><code>GET /api/pairs/{id}/trades</code></h2>\n<p>Recent trades or LP events for one pair. A <strong>combined-pair</strong> id\n(<code>&lt;aid1&gt;_&lt;aid2&gt;</code>) interleaves rows across every fee tier; a single-tier id\nreturns just that pool&#39;s rows.</p>\n<p>Query params:</p>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Default</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>kind</code></td>\n<td><code>Trade | lp</code></td>\n<td><code>Trade</code></td>\n<td><code>lp</code> returns Deposit + Withdraw events.</td>\n</tr>\n<tr>\n<td><code>limit</code></td>\n<td>int, 1..200</td>\n<td>50</td>\n<td></td>\n</tr>\n<tr>\n<td><code>before</code></td>\n<td>int (unix seconds)</td>\n<td><code>now</code></td>\n<td>Cursor mode — &quot;load more&quot; pagination.</td>\n</tr>\n<tr>\n<td><code>offset</code></td>\n<td>int ≥ 0</td>\n<td>—</td>\n<td>Numbered pagination. When present, overrides <code>before</code>.</td>\n</tr>\n<tr>\n<td><code>count</code></td>\n<td>bool</td>\n<td>false</td>\n<td>Also return <code>total</code> (pool&#39;s full row count) for &quot;Showing X to Y of N&quot;.</td>\n</tr>\n<tr>\n<td><code>include_unconfirmed</code></td>\n<td>bool</td>\n<td>true</td>\n<td>UI shows unconfirmed with a marker; CG endpoints always exclude.</td>\n</tr>\n</tbody></table>\n<p>In offset mode the response echoes <code>offset</code> and <code>limit</code>, and (when <code>count=true</code>) <code>total</code>; <code>before</code> is <code>null</code>.</p>\n<p>Trade response:</p>\n<pre><code class=\"language-json\">{\n  &quot;trades&quot;: [\n    {\n      &quot;trade_id&quot;: 81729,\n      &quot;timestamp&quot;: 1747400940,\n      &quot;height&quot;: 3863500,\n      &quot;aid_in&quot;: 0, &quot;aid_out&quot;: 31,\n      &quot;amount_in&quot;:  &quot;1000000000&quot;,\n      &quot;amount_out&quot;: &quot;29342934&quot;,\n      &quot;side&quot;: &quot;buy&quot;,                   // computed: aid_in == aid1 → buy\n      &quot;price_native&quot;: 29.34293421,\n      &quot;price_usd&quot;: 0.99,               // when aid1 == 0 (BEAM)\n      &quot;value_usd&quot;: 9.93,               // volume_aid1 (in whole units) × BEAM/USD when aid1 == 0\n      &quot;confirmed&quot;: true,\n      &quot;confirmations&quot;: 80              // truncated to 80 once confirmed\n    }\n  ],\n  &quot;before&quot;: 1747400940                 // oldest timestamp in the page (next page cursor)\n}\n</code></pre>\n<p>LP-event response (<code>kind=lp</code>):</p>\n<pre><code class=\"language-json\">{\n  &quot;trades&quot;: [\n    {\n      &quot;event_id&quot;: 1027,\n      &quot;timestamp&quot;: 1747400940,\n      &quot;height&quot;: 3863500,\n      &quot;kind&quot;: &quot;Deposit&quot;,\n      &quot;amount1&quot;: &quot;10000000000&quot;,\n      &quot;amount2&quot;: &quot;352115210000&quot;,\n      &quot;amount_ctl&quot;: &quot;1095445115&quot;,\n      &quot;liquidity_pct&quot;: 0.18,           // signed share of the pool this event added/removed (Withdraw &lt; 0)\n      &quot;confirmed&quot;: true\n    }\n  ],\n  &quot;before&quot;: 1747400940\n}\n</code></pre>\n<p><code>Cache-Control: public, max-age=15</code>.</p>\n<h2 id=\"api-get-api-pairs-id-liquidity\"><code>GET /api/pairs/{id}/liquidity</code></h2>\n<p>Pooled-amount time series for one pool, decomposed by the source of the reserve changes. Drives the trade page&#39;s Pool History chart (two series: pooled aid1 + pooled aid2). A <strong>combined-pair</strong> id (<code>&lt;aid1&gt;_&lt;aid2&gt;</code>) sums the series across every fee tier per bucket (so it matches the grouped <code>tvl_usd</code> / pooled totals); a single-tier id returns that pool&#39;s series.</p>\n<p>Query params:</p>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Default</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>source</code></td>\n<td><code>total | lp | trades</code></td>\n<td><code>total</code></td>\n<td><code>total</code> = actual pooled reserves; <code>lp</code> = cumulative net deposits; <code>trades</code> = cumulative reserve change from swaps. <code>total ≈ lp + trades</code>.</td>\n</tr>\n<tr>\n<td><code>interval</code></td>\n<td><code>1h | 1d</code></td>\n<td><code>1d</code></td>\n<td>Bucket width.</td>\n</tr>\n<tr>\n<td><code>from</code></td>\n<td>int (unix seconds)</td>\n<td>—</td>\n<td>Trim returned buckets (cumulative series stay correct at the left edge).</td>\n</tr>\n<tr>\n<td><code>to</code></td>\n<td>int (unix seconds)</td>\n<td>—</td>\n<td></td>\n</tr>\n</tbody></table>\n<p>Response (<code>amount*</code> are groths of aid1/aid2; divide by <code>10^decimalsN</code>):</p>\n<pre><code class=\"language-json\">{\n  &quot;series&quot;: [\n    { &quot;ts&quot;: 1700000000, &quot;amount1&quot;: &quot;545527910000000&quot;, &quot;amount2&quot;: &quot;82055439000000&quot; }\n  ],\n  &quot;decimals1&quot;: 8,\n  &quot;decimals2&quot;: 8\n}\n</code></pre>\n<p><code>Cache-Control: public, max-age=30</code>.</p>\n<h2 id=\"api-get-api-assets\"><code>GET /api/assets</code></h2>\n<p>Catalog of every asset known to the backend. Wholesale (no pagination) — there are ~200 assets on mainnet today; small enough to send in one shot.</p>\n<pre><code class=\"language-json\">{\n  &quot;assets&quot;: [\n    {\n      &quot;aid&quot;: 0,\n      &quot;name&quot;: &quot;Beam&quot;, &quot;short_name&quot;: &quot;BEAM&quot;, &quot;unit_name&quot;: &quot;BEAM&quot;,\n      &quot;description&quot;: &quot;Native BEAM asset&quot;,\n      &quot;decimals&quot;: 8,\n      &quot;is_imposter&quot;: false, &quot;imposter_reason&quot;: null,\n      &quot;emission&quot;:  &quot;26279999976873600&quot;,        // for aid 0: BEAM current circulation\n      &quot;minted_at_height&quot;: null,                // on-chain registration height\n      &quot;minted_at_ts&quot;: null,                    // epoch seconds for minted_at_height\n      &quot;minter_cid&quot;: null,\n      &quot;max_supply&quot;: &quot;26280000000000000&quot;,       // for aid 0: BEAM total circulation\n      &quot;pool_count&quot;: 47\n    }\n  ]\n}\n</code></pre>\n<p><code>Cache-Control: public, max-age=30</code>.</p>\n<h2 id=\"api-get-api-asset-aid\"><code>GET /api/asset/{aid}</code></h2>\n<p>Single asset metadata + every active pool it participates in.</p>\n<pre><code class=\"language-json\">{\n  &quot;aid&quot;: 31,\n  &quot;name&quot;: &quot;Tether USD&quot;,\n  &quot;short_name&quot;: &quot;USDT&quot;,\n  &quot;unit_name&quot;: &quot;USDT&quot;,\n  &quot;description&quot;: &quot;Wrapped USDT bridged from Ethereum&quot;,\n  &quot;decimals&quot;: 8,\n  &quot;is_imposter&quot;: false,\n  &quot;emission&quot;: &quot;1000000000000000&quot;,\n  &quot;minted_at_height&quot;: 1234567,         // on-chain registration height\n  &quot;minter_cid&quot;: &quot;295fe749…d868&quot;,       // null if not minter-issued\n  &quot;max_supply&quot;: &quot;5000000000000000&quot;,    // null if uncapped\n  &quot;pools&quot;: [\n    { &quot;pair_id&quot;: 17, &quot;aid1&quot;: 0, &quot;aid2&quot;: 31, &quot;kind&quot;: 1, &quot;tvl_usd&quot;: 7613.10, &quot;amount&quot;: &quot;31946584614&quot; }\n  ]\n}\n</code></pre>\n<p>The <code>pools.tvl_usd</code> field is best-effort: it requires BEAM to be one of the sides (so the USD reference is reachable in one hop). Otherwise <code>null</code>. <code>pools.amount</code> is this asset&#39;s reserve in the pool — groths as a decimal string, <code>null</code> until the pool has a state snapshot.</p>\n<p>400 (<code>BAD_REQUEST</code>) if <code>aid</code> isn&#39;t a non-negative integer; 404 (<code>ASSET_NOT_FOUND</code>) if no row exists.</p>\n<p><code>Cache-Control: public, max-age=30</code>.</p>\n<h2 id=\"api-get-api-asset-aid-history\"><code>GET /api/asset/{aid}/history</code></h2>\n<p>Mint / burn / create / destroy events for an asset. Pass-through over the explorer&#39;s <code>/asset?id=&lt;aid&gt;</code>, lightly parsed and cached.</p>\n<p>Query params:</p>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Default</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>limit</code></td>\n<td>int, 1..500</td>\n<td>100</td>\n<td></td>\n</tr>\n</tbody></table>\n<p>Response:</p>\n<pre><code class=\"language-json\">{\n  &quot;aid&quot;: 31,\n  &quot;history&quot;: [\n    {\n      &quot;height&quot;: 3862500,\n      &quot;event&quot;: &quot;Mint&quot;,\n      &quot;amount&quot;:       &quot;500000000&quot;,\n      &quot;total_amount&quot;: &quot;1000500000000&quot;,\n      &quot;extra&quot;: &quot;&quot;\n    }\n  ],\n  &quot;cached&quot;: false\n}\n</code></pre>\n<ul>\n<li>400 if <code>aid == 0</code> (BEAM) — there&#39;s no <code>/asset?id=0</code> endpoint on the explorer; the asset detail page reads BEAM supply from <code>/api/asset/0</code> instead.</li>\n<li>In-process LRU cache, 5-minute TTL. Cache key includes <code>limit</code> so different page sizes don&#39;t collide.</li>\n</ul>\n<p><code>Cache-Control: public, max-age=300</code>.</p>\n<h2 id=\"api-get-api-asset-aid-distribution\"><code>GET /api/asset/{aid}/distribution</code></h2>\n<p>How much of an asset each contract currently has locked, plus the unlocked remainder. Live state, no history.</p>\n<p>No query params.</p>\n<p>Response:</p>\n<pre><code class=\"language-json\">{\n  &quot;aid&quot;: 7,\n  &quot;entries&quot;: [\n    {\n      &quot;cid&quot;: &quot;b8944fd3f6a62697a89b2a55acd1cb2e3893dadece99569706efa1da847dd440&quot;,\n      &quot;kind&quot;: &quot;Nephrite v1&quot;,\n      &quot;amount&quot;: &quot;14658636293475&quot;\n    }\n  ],\n  &quot;unlocked&quot;: &quot;173224572110680&quot;,\n  &quot;total&quot;: &quot;187883208404155&quot;\n}\n</code></pre>\n<ul>\n<li><code>entries</code> — one row per contract holding a non-zero balance of the asset, sorted by amount descending for <code>aid == 0</code> (explorer order otherwise). <code>kind</code> is the parser&#39;s human-readable shader name (&quot;DEX v0&quot;, &quot;Nephrite v1&quot;, …), or the shader hash hex when the parser doesn&#39;t recognise the contract. Amounts are groths as decimal strings.</li>\n<li><code>unlocked</code> — supply not held by any contract; <code>total</code> — <code>unlocked</code> plus the sum of <code>entries</code>.</li>\n<li><code>aid &gt; 0</code> is a pass-through over the explorer&#39;s <code>/asset?id=&lt;aid&gt;</code> &quot;Asset distribution&quot; table.</li>\n<li><code>aid == 0</code> (BEAM) is synthesized instead — the explorer rejects <code>/asset?id=0</code> (BEAM has no asset-registry row), so the backend collects the aid-0 entry of every contract&#39;s Locked Funds table from <code>/contracts</code> and anchors <code>unlocked</code> to the circulating supply it tracks (<code>emission</code> on <code>/api/asset/0</code>). If the supply figure is momentarily unavailable, <code>unlocked</code> degrades to <code>&quot;0&quot;</code> and <code>total</code> covers only the locked sum.</li>\n</ul>\n<p><code>Cache-Control: public, max-age=30</code>.</p>\n<h2 id=\"api-get-api-network\"><code>GET /api/network</code></h2>\n<p>Canonical snapshot of current network health — hashrate, difficulty, average block time, and the chain tip — plus the last 60 blocks. Everything derives from a single read of <code>block_metrics</code>, and this is the single source of truth for the <code>network_hashrate</code> reported by <code>/api/mining/pools</code> and shown on the Health page.</p>\n<p>No query params.</p>\n<pre><code class=\"language-json\">{\n  &quot;hashrate&quot;: 78528.17,\n  &quot;difficulty&quot;: 5141867.25,\n  &quot;avg_block_time&quot;: 65.58,\n  &quot;tip_height&quot;: 3935205,\n  &quot;recent&quot;: [\n    {\n      &quot;height&quot;: 3935146,\n      &quot;ts&quot;: 1783283812,\n      &quot;difficulty&quot;: 5001484.5,\n      &quot;kernels&quot;: 2\n    }\n  ]\n}\n</code></pre>\n<ul>\n<li><code>hashrate</code> — network-wide hashrate in Sol/s (BeamHash III), the time-weighted average <code>Σ difficulty / Δt</code> across the window; <code>null</code> until at least two blocks are indexed.</li>\n<li><code>difficulty</code> — difficulty of the latest block; <code>null</code> if <code>block_metrics</code> is empty.</li>\n<li><code>avg_block_time</code> — mean seconds between blocks, <code>Δt / (N − 1)</code> across the window; <code>null</code> until at least two blocks are indexed.</li>\n<li><code>tip_height</code> — height of the current chain tip; <code>null</code> if <code>block_metrics</code> is empty.</li>\n<li><code>recent</code> — the last 60 blocks (fewer if the chain is shorter), ordered oldest → newest. Each entry:<ul>\n<li><code>height</code> — block height.</li>\n<li><code>ts</code> — block timestamp in <strong>unix seconds</strong> (note: <code>/api/mining/blocks</code> reports <code>ts</code> as an ISO 8601 string; this endpoint uses epoch seconds).</li>\n<li><code>difficulty</code> — that block&#39;s difficulty.</li>\n<li><code>kernels</code> — number of kernels in the block.</li>\n</ul>\n</li>\n</ul>\n<p>The window is the last 60 blocks (≈ 1h at the 60s block target), matching the <code>/api/charts/hashrate</code> convention.</p>\n<p><code>Cache-Control: public, max-age=30</code>.</p>\n<h2 id=\"api-get-api-mining-pools\"><code>GET /api/mining/pools</code></h2>\n<p>Current snapshot of every tracked mining pool plus the live network hashrate.</p>\n<p>No query params.</p>\n<pre><code class=\"language-json\">{\n  &quot;network_hashrate&quot;: 1234567.89,\n  &quot;block_height&quot;: 3863512,\n  &quot;blocks_24h_total&quot;: 1438,\n  &quot;pools&quot;: [\n    {\n      &quot;id&quot;: &quot;herominers&quot;,\n      &quot;name&quot;: &quot;HeroMiners&quot;,\n      &quot;website&quot;: &quot;https://beam.herominers.com&quot;,\n      &quot;payout_scheme&quot;: &quot;PPLNS&quot;,\n      &quot;hashrate&quot;: 987654.32,\n      &quot;miners&quot;: 120,\n      &quot;workers&quot;: 145,\n      &quot;blocks_24h&quot;: 38,\n      &quot;last_block_height&quot;: 3863400,\n      &quot;last_block_ts&quot;: &quot;2025-05-16T10:22:00.000Z&quot;,\n      &quot;fee&quot;: 1.0,\n      &quot;min_payout&quot;: 1.0,\n      &quot;updated_at&quot;: &quot;2025-05-16T10:30:00.000Z&quot;,\n      &quot;hashrate_series&quot;: [950000, 970000, 987654],\n      &quot;blocks_past_hour&quot;: 2,\n      &quot;blocks_past_24h&quot;: 41\n    }\n  ]\n}\n</code></pre>\n<ul>\n<li><code>network_hashrate</code> — network-wide hashrate in Sol/s, derived as <code>Σ difficulty / Δt</code> across the last 60 blocks; <code>null</code> if <code>block_metrics</code> is empty.</li>\n<li><code>block_height</code> — height of the current network tip; <code>null</code> if <code>block_metrics</code> is empty.</li>\n<li><code>blocks_24h_total</code> — total network blocks in the past 24h (the distribution donut&#39;s denominator; the <code>Unknown</code> slice is this minus the attributed sum). <code>0</code> if <code>block_metrics</code> is empty.</li>\n<li>Per-pool fields:<ul>\n<li><code>hashrate</code> — pool hashrate in Sol/s as self-reported by the pool&#39;s API; <code>null</code> if the pool is unreachable.</li>\n<li><code>miners</code>, <code>workers</code>, <code>blocks_24h</code>, <code>last_block_height</code>, <code>last_block_ts</code>, <code>fee</code>, <code>min_payout</code>, <code>updated_at</code> — all <code>null</code> when the pool is offline or has never been polled successfully.</li>\n<li><code>fee</code> — pool fee in percent (e.g. <code>1.0</code> = 1%).</li>\n<li><code>min_payout</code> — minimum payout in BEAM.</li>\n<li><code>hashrate_series</code> — last ≤ 30 non-null hashrate snapshots (Sol/s), ordered oldest → newest. Empty array if no data yet.</li>\n<li><code>blocks_past_hour</code> — network blocks in the past hour attributed to this pool. <code>0</code> if none.</li>\n<li><code>blocks_past_24h</code> — network blocks in the past 24h attributed to this pool. <code>0</code> if none.</li>\n</ul>\n</li>\n</ul>\n<p>Pool stats are scraped from each pool&#39;s own API on every new block; the freshness of each entry reflects when the poll last succeeded.</p>\n<p><code>Cache-Control: public, max-age=60</code>.</p>\n<h2 id=\"api-get-api-mining-blocks\"><code>GET /api/mining/blocks</code></h2>\n<p>Recent blocks with best-effort pool attribution, most-recent first.</p>\n<p>Query params:</p>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Default</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>limit</code></td>\n<td>int, 1..200</td>\n<td>50</td>\n<td></td>\n</tr>\n<tr>\n<td><code>offset</code></td>\n<td>int ≥ 0</td>\n<td>0</td>\n<td>Numbered pagination.</td>\n</tr>\n</tbody></table>\n<pre><code class=\"language-json\">{\n  &quot;blocks&quot;: [\n    {\n      &quot;height&quot;: 3863512,\n      &quot;ts&quot;: &quot;2025-05-16T10:30:00.000Z&quot;,\n      &quot;mined_by&quot;: &quot;HeroMiners&quot;\n    }\n  ]\n}\n</code></pre>\n<ul>\n<li><code>ts</code> — ISO 8601 timestamp of the block (<code>block_metrics.block_ts</code>).</li>\n<li><code>mined_by</code> — pool display name resolved from the pool&#39;s own self-reported found-blocks feed; <code>null</code> = unattributed. BEAM blocks carry no on-chain pool tag, so attribution is best-effort only.</li>\n</ul>\n<p><code>Cache-Control: public, max-age=30</code>.</p>\n<h2 id=\"api-get-api-charts-series\"><code>GET /api/charts/{series}</code></h2>\n<p>Historical chart data for a named series. All series share the same response shape:</p>\n<pre><code class=\"language-json\">{\n  &quot;series&quot;: [\n    { &quot;ts&quot;: 1700000000, &quot;value&quot;: 1234567.89 }\n  ]\n}\n</code></pre>\n<p><code>ts</code> is unix seconds (integer). <code>value</code> is a JSON number. Points are ascending by <code>ts</code>. Null values are omitted. Each series is served from an in-process server-side cache (pre-warmed at boot, refreshed every 30 minutes), so the response is fast even for series that require full-history Postgres aggregates.</p>\n<p>Responses support <code>ETag</code> / <code>If-None-Match</code> conditional requests; a 304 is returned when the cached series has not changed.</p>\n<h3 id=\"api-query-params\">Query params</h3>\n<p>All optional. With none, the endpoint returns the full daily history — the original shape, unchanged.</p>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Default</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>res</code></td>\n<td><code>1m</code> | <code>1h</code> | <code>1d</code></td>\n<td><code>1d</code></td>\n<td>Resolution. <code>1m</code> applies only in range mode (below); in default mode any unrecognized value — including <code>1m</code> — serves <code>1d</code>.</td>\n</tr>\n<tr>\n<td><code>from</code></td>\n<td>unix seconds</td>\n<td>—</td>\n<td>Start of a zoom window. Must be sent together with <code>to</code>.</td>\n</tr>\n<tr>\n<td><code>to</code></td>\n<td>unix seconds</td>\n<td>—</td>\n<td>End of a zoom window. Must be greater than <code>from</code>.</td>\n</tr>\n</tbody></table>\n<p><strong>Default mode</strong> — no <code>from</code>/<code>to</code>. Returns the full-history series at daily (<code>res=1d</code>) or hourly (<code>res=1h</code>) resolution. Hourly exists for every series <strong>except</strong> <code>beam-vol</code>, <code>dex-vol</code>, <code>blackhole</code>, <code>pools-created</code>, and <code>pools-closed</code>; requesting <code>res=1h</code> on those silently serves <code>1d</code>. Both resolutions come from the in-process cache described above, so <code>Cache-Control</code> is the per-series <code>max-age</code> in the table below.</p>\n<p><strong>Range (&quot;zoom&quot;) mode</strong> — <code>from</code> <strong>and</strong> <code>to</code> both present. Returns only the points inside <code>[from, to)</code>, served from a separate tile-quantized, bounded cache, at <code>res=1m|1h|1d</code> (default <code>1d</code>). Supported for every series <strong>except</strong> <code>beam-vol</code>, <code>dex-vol</code>, <code>blackhole</code>, <code>pools-created</code>, and <code>pools-closed</code>, which are daily-only and return an empty <code>series</code> here. Bad bounds (<code>to ≤ from</code>, or non-numeric) yield <code>400 {&quot;error&quot;:&quot;bad from/to&quot;}</code>. <code>Cache-Control: public, max-age=86400</code> once the whole window has settled (<code>to</code> older than the ~80-minute / 80-block confirmation horizon), otherwise <code>max-age=60</code>.</p>\n<p>Both modes return the same <code>{ &quot;series&quot;: [ … ] }</code> shape and honor <code>ETag</code> / <code>If-None-Match</code> (304 when unchanged).</p>\n<p>Available series (the full set is defined in <code>backend/src/api/routes/charts.ts</code>):</p>\n<table>\n<thead>\n<tr>\n<th>Series name</th>\n<th>Unit</th>\n<th><code>max-age</code></th>\n<th>Source</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>hashrate</code></td>\n<td>Sol/s</td>\n<td>600 s</td>\n<td>Postgres: <code>Σ difficulty / Δt</code> per day from <code>block_metrics</code></td>\n</tr>\n<tr>\n<td><code>difficulty</code></td>\n<td>raw difficulty</td>\n<td>600 s</td>\n<td>Postgres: daily average from <code>block_metrics</code></td>\n</tr>\n<tr>\n<td><code>block-time</code></td>\n<td>seconds</td>\n<td>600 s</td>\n<td>Postgres: daily average block interval from <code>block_metrics</code></td>\n</tr>\n<tr>\n<td><code>tvl</code></td>\n<td>USD</td>\n<td>1800 s</td>\n<td>Postgres: end-of-day pooled reserves × BEAM/USD per day</td>\n</tr>\n<tr>\n<td><code>price</code></td>\n<td>BEAM/USD</td>\n<td>600 s</td>\n<td>Postgres: daily closing price from <code>oracle_snapshots</code></td>\n</tr>\n<tr>\n<td><code>coinbase</code></td>\n<td>count/day</td>\n<td>600 s</td>\n<td>Postgres: blocks per day (one coinbase output per block)</td>\n</tr>\n<tr>\n<td><code>assets</code></td>\n<td>cumulative count</td>\n<td>600 s</td>\n<td>Postgres: cumulative registered confidential assets</td>\n</tr>\n<tr>\n<td><code>dex-volume</code></td>\n<td>USD</td>\n<td>1800 s</td>\n<td>Postgres: daily DEX volume in USD</td>\n</tr>\n<tr>\n<td><code>beam-vol</code></td>\n<td>percent (annualized)</td>\n<td>1800 s</td>\n<td>Postgres: 30-day rolling realized volatility of BEAM/USD</td>\n</tr>\n<tr>\n<td><code>dex-vol</code></td>\n<td>percent (annualized)</td>\n<td>1800 s</td>\n<td>Postgres: TVL-weighted per-pool 30-day rolling realized volatility</td>\n</tr>\n<tr>\n<td><code>pools-created</code></td>\n<td>cumulative count</td>\n<td>1800 s</td>\n<td>Postgres: cumulative pools created over time, from <code>pools.created_at_height</code></td>\n</tr>\n<tr>\n<td><code>pools-closed</code></td>\n<td>cumulative count</td>\n<td>1800 s</td>\n<td>Postgres: cumulative pools destroyed over time, from <code>pools.destroyed_at_height</code></td>\n</tr>\n<tr>\n<td><code>transactions-daily</code></td>\n<td>count/day</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>transactions-total</code></td>\n<td>cumulative count</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>txos-total</code></td>\n<td>cumulative count</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>utxos-total</code></td>\n<td>cumulative count</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>size-total</code></td>\n<td>bytes</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>archive-total</code></td>\n<td>bytes</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>shielded-ins-daily</code></td>\n<td>count/day</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>shielded-ins-total</code></td>\n<td>cumulative count</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>shielded-outs-daily</code></td>\n<td>count/day</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>shielded-outs-total</code></td>\n<td>cumulative count</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>contracts-total</code></td>\n<td>cumulative count</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>fees-daily</code></td>\n<td>groth/day</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>fees-total</code></td>\n<td>cumulative groth</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>contract-calls-daily</code></td>\n<td>count/day</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>contract-calls-total</code></td>\n<td>cumulative count</td>\n<td>600 s</td>\n<td>Explorer <code>/hdrs</code></td>\n</tr>\n<tr>\n<td><code>blackhole</code></td>\n<td>—</td>\n<td>1800 s</td>\n<td>Multi-series: <code>series</code> is not a flat <code>SeriesPoint[]</code> but an array of per-asset cumulative-lock series (one line per asset locked in the BlackHole contract).</td>\n</tr>\n</tbody></table>\n<p>In default mode, <code>Cache-Control</code> is the per-series <code>max-age</code> listed above; range mode is scoped under <strong>Query params</strong> above.</p>\n<h2 id=\"api-get-api-bans-actions\"><code>GET /api/bans/actions</code></h2>\n<p>Full BANS registry action history (oldest→newest), from <code>contract_call_events</code>.</p>\n<pre><code class=\"language-json\">{\n  &quot;actions&quot;: [\n    { &quot;height&quot;: 1896200, &quot;block_ts&quot;: &quot;2021-05-01T12:00:00.000Z&quot;, &quot;method&quot;: &quot;Register&quot;, &quot;name&quot;: &quot;syntaxjak&quot;, &quot;args&quot;: { &quot;Periods&quot;: 3, &quot;name&quot;: &quot;syntaxjak&quot; } }\n  ],\n  &quot;meta&quot;: { &quot;total&quot;: 999, &quot;first_height&quot;: 1896200, &quot;last_height&quot;: 3922383 }\n}\n</code></pre>\n<p><code>Cache-Control: public, max-age=60</code>. Returns empty <code>actions</code> when <code>BANS_CID</code> is unset.</p>\n<h2 id=\"api-get-api-bridge-health\"><code>GET /api/bridge/health</code></h2>\n<p>Liveness and peg backing for the six Beam↔EVM Pipe bridges — four b-asset bridges\nand BEAM/WBEAM on both Ethereum mainnet and Arbitrum One.</p>\n<pre><code class=\"language-json\">{\n  &quot;bridges&quot;: [\n    {\n      &quot;bridge&quot;: &quot;busdt&quot;, &quot;label&quot;: &quot;bUSDT&quot;, &quot;chain_id&quot;: 1, &quot;aid&quot;: 37,\n      &quot;eth_pipe&quot;: &quot;0x7c3fe09e86b0d8661d261a49bfa385536b7077f9&quot;,\n      &quot;eth_token&quot;: &quot;0xdAC17F958D2ee523a2206206994597C13D831ec7&quot;,\n      &quot;asset_symbol&quot;: &quot;bUSDT&quot;,\n      &quot;outgoing&quot;: { &quot;pending&quot;: 99, &quot;relayed&quot;: 0, &quot;failed&quot;: 0, &quot;unknown&quot;: 0, &quot;total&quot;: 99 },\n      &quot;incoming&quot;: { &quot;not_delivered&quot;: 2, &quot;unclaimed&quot;: 2, &quot;complete&quot;: 136, &quot;unknown&quot;: 0, &quot;total&quot;: 140 },\n      &quot;oldest_open_ts&quot;: &quot;2022-06-14T09:12:00.000Z&quot;,\n      &quot;last_message_ts&quot;: &quot;2026-08-08T13:56:26.000Z&quot;,\n      &quot;unclaimed_amount&quot;: 41.5,\n      &quot;escrow&quot;: { &quot;locked&quot;: 3701.4022, &quot;decimals&quot;: 6, &quot;observed_at&quot;: &quot;2026-08-08T23:40:00.000Z&quot; },\n      &quot;minted&quot;: 3688.28,\n      &quot;collateral_ratio&quot;: 0.9964,\n      &quot;settlement_source&quot;: &quot;etherscan&quot;\n    }\n  ],\n  &quot;tvl_usd&quot;: 1234567.89,\n  &quot;tvl_priced&quot;: 6,\n  &quot;settlement_available&quot;: true\n}\n</code></pre>\n<p><code>tvl_usd</code> is the USD value of all locked collateral, priced off each bridge&#39;s\nBeam-side asset (the wrapped asset tracks its collateral 1:1). Bridges with no\nBEAM-quoted pool are excluded rather than counted as zero; <code>tvl_priced</code> says how\nmany contributed.</p>\n<p>Status vocabularies differ by direction, because the underlying contract states do:</p>\n<ul>\n<li><code>beam2eth</code> — <code>pending</code> (no settling Ethereum tx seen), <code>relayed</code>, <code>failed</code>, <code>unknown</code>.</li>\n<li><code>eth2beam</code> — <code>not_delivered</code> (the relayer never pushed it to Beam), <code>unclaimed</code>\n(delivered; the recipient hasn&#39;t signed <code>ReceiveFunds</code>), <code>complete</code>, <code>unknown</code>.</li>\n</ul>\n<p><code>unclaimed</code> is <strong>not</strong> an error: only the recipient can claim, so a message can sit\nthere indefinitely. Don&#39;t count it as a bridge failure.</p>\n<p><code>collateral_ratio</code> is minted supply ÷ locked collateral. ≤1.0 means every wrapped\nunit is backed; small deviations are in-flight messages and relayer fees, and a\nratio above 1 means more has been issued than is held.</p>\n<p><strong>Custody direction differs per bridge.</strong> The b-asset bridges lock collateral on\nEthereum and mint on Beam, so <code>escrow.locked</code> is the Ethereum Pipe&#39;s balance and\n<code>minted</code> is the Beam asset&#39;s emission. BEAM/WBEAM is the reverse: native BEAM is\nlocked in the <em>Beam</em> Pipe and WBEAM is minted on Ethereum, so <code>escrow.locked</code> is\nthe Beam-side locked amount and <code>minted</code> is the WBEAM ERC20 total supply.</p>\n<p><code>settlement_available</code> is <code>false</code> when no <code>ETHERSCAN_API_KEY</code> is configured. In that\nstate <code>beam2eth</code> messages stay <code>pending</code> and no failure can be observed —\n<code>&quot;failed&quot;: 0</code> then means &quot;unverifiable&quot;, not &quot;none&quot;. <code>Cache-Control: public, max-age=30</code>.</p>\n<h2 id=\"api-get-api-bridge-lookup\"><code>GET /api/bridge/lookup</code></h2>\n<p>Point lookup for a single transfer — &quot;I sent this, where is it?&quot;. Takes either\nside&#39;s identifier via <code>q</code>: an Ethereum/Arbitrum transaction hash, or a Beam\nkernel ID.</p>\n<pre><code class=\"language-json\">{\n  &quot;query&quot;: &quot;0x9a51…&quot;, &quot;kind&quot;: &quot;evm_tx&quot;, &quot;resolved_height&quot;: null,\n  &quot;matches&quot;: [\n    {\n      &quot;bridge&quot;: &quot;beam-wbeam&quot;, &quot;label&quot;: &quot;BEAM / WBEAM&quot;, &quot;direction&quot;: &quot;eth2beam&quot;,\n      &quot;msg_id&quot;: 219, &quot;status&quot;: &quot;unclaimed&quot;, &quot;amount&quot;: 605.47244962,\n      &quot;role&quot;: &quot;origin&quot;,\n      &quot;explanation&quot;: &quot;Delivered to Beam and waiting for you to claim it. …&quot;\n    }\n  ]\n}\n</code></pre>\n<p><code>kind</code> is <code>evm_tx</code>, <code>beam_kernel</code>, or <code>unrecognised</code>. Both identifiers are 32\nbytes so the input alone can&#39;t distinguish them: the EVM side is tried first,\nthen the kernel is resolved to a Beam height and matched against outgoing\nmessages at that height (a height can carry several, so all are returned).</p>\n<p><code>explanation</code> is plain-language guidance for the current state — notably, a\n<code>pending</code> Beam→Ethereum transfer or a <code>not_delivered</code> message usually means the\nrelayer is waiting for Ethereum gas to come down, not that anything is lost.\n<code>Cache-Control: public, max-age=10</code> — short, because a pending transfer&#39;s state\nis exactly what the caller is watching.</p>\n<h2 id=\"api-get-api-bridge-messages\"><code>GET /api/bridge/messages</code></h2>\n<p>Individual bridge transfers, newest first.</p>\n<p>Query params: <code>bridge</code>, <code>direction</code> (<code>beam2eth</code>|<code>eth2beam</code>), <code>status</code>,\n<code>sort</code>, <code>dir</code>, <code>limit</code> (default 50, max 500), <code>offset</code>.</p>\n<p><code>sort</code> is one of <code>age</code> (default), <code>amount</code>, <code>fee</code>, <code>msg_id</code>, <code>bridge</code>, <code>status</code>,\n<code>direction</code>; <code>dir</code> is <code>desc</code> (default) or <code>asc</code>. Unknown values fall back to the\ndefaults rather than erroring. Note <code>amount</code> sorts on the raw stored value, which\nis denominated in each side&#39;s own units — meaningful within one bridge, less so\nacross bridges with different decimals.</p>\n<pre><code class=\"language-json\">{\n  &quot;messages&quot;: [\n    {\n      &quot;bridge&quot;: &quot;beam-wbeam&quot;, &quot;direction&quot;: &quot;beam2eth&quot;, &quot;msg_id&quot;: 496,\n      &quot;status&quot;: &quot;pending&quot;, &quot;amount&quot;: 15000.0, &quot;relayer_fee&quot;: 95.42684516,\n      &quot;receiver&quot;: &quot;24c32736a24f2ccc95a3249b17ea5c23222df71c&quot;,\n      &quot;src_height&quot;: 3981297, &quot;src_block&quot;: null,\n      &quot;src_ts&quot;: &quot;2026-08-07T01:03:30.000Z&quot;, &quot;src_tx&quot;: null,\n      &quot;settle_tx&quot;: null, &quot;settle_block&quot;: null, &quot;settle_ts&quot;: null\n    }\n  ],\n  &quot;total&quot;: 1283, &quot;limit&quot;: 50, &quot;offset&quot;: 0\n}\n</code></pre>\n<p><code>amount</code> and <code>relayer_fee</code> are scaled to the side the message was observed on:\nBeam-side decimals for <code>beam2eth</code>, Ethereum-side for <code>eth2beam</code>. These differ —\nbUSDT is 8 decimals on Beam against USDT&#39;s 6 on Ethereum. <code>receiver</code> is a 20-byte\nEthereum address for <code>beam2eth</code> and a 33-byte Beam pubkey for <code>eth2beam</code>, hex, no\n<code>0x</code>. <code>Cache-Control: public, max-age=30</code>.</p>\n<h2 id=\"api-quote-endpoint-intentionally-not-present\">Quote endpoint — intentionally not present</h2>\n<p>The swap panel asks the AMM shader for quotes directly (<code>pool_trade</code> with <code>bPredictOnly=1</code>) via the user&#39;s wallet. We <strong>don&#39;t</strong> mirror that on the server because:</p>\n<ol>\n<li>The shader has to run anyway when the wallet executes the trade.</li>\n<li>A server quote would drift from on-chain reality between request and broadcast.</li>\n<li>Local AMM math is trivial (constant product) for instant UI feedback before the wallet&#39;s authoritative quote arrives.</li>\n</ol>\n<p>The swap panel&#39;s local estimate uses <code>dy = r2·dx / (r1+dx) · (1 - fee)</code> with the latest <code>reserve1</code> / <code>reserve2</code> from <code>/api/pairs/{id}</code>. See <a href=\"frontend.md#wallet-integration\">frontend.md §Wallet integration</a>.</p>\n<h2 id=\"api-usd-valuation\">USD valuation</h2>\n<p>Backed by <code>backend/src/api/repos/usd.ts:loadUsdTable</code>. For each request that needs USD figures, the route loads:</p>\n<ul>\n<li><code>beam_usd</code> — latest <code>oracle_snapshots.beam_usd</code>.</li>\n<li>A <code>perAid: Map&lt;aid, usdPerWholeUnit&gt;</code> built by routing each non-BEAM asset through its deepest BEAM-quoted pool (highest <code>reserve1</code> BEAM groths). Assets without a BEAM-quoted path get no rate.</li>\n</ul>\n<p>The same table is used everywhere — <code>/api/stats</code>, <code>/api/pairs</code>, <code>/api/pairs/{id}</code>, <code>/cg/tickers</code> — so USD numbers match across surfaces by construction.</p>\n<h2 id=\"api-freshness-model\">Freshness model</h2>\n<p>The frontend polls. There&#39;s no WebSocket in v1.</p>\n<ul>\n<li><code>/api/stats</code> — every 60 s.</li>\n<li><code>/api/pairs?...</code> — re-fetched on mount or when sort/filter changes. Not auto-polled.</li>\n<li><code>/api/pairs/{id}</code> — every 30 s on the detail page.</li>\n<li><code>/api/pairs/{id}/ohlcv</code> — once on mount, plus on interval/denom change and on scroll-back (uses the <code>more.to</code> cursor).</li>\n<li><code>/api/pairs/{id}/trades</code> — initial load + 30 s top-of-feed refresh that splices new trades onto the head.</li>\n</ul>\n<p>The <code>useFetcher</code> / <code>usePolling</code> hooks live in <code>frontend/src/app/containers/Screener/hooks.ts</code>. They keep last-known data on screen during refreshes so the UI doesn&#39;t flicker between loaded and &quot;Loading…&quot; every interval.</p>\n<p>In-wallet, the same hooks run unchanged. A future v1.x can opt into per-block refresh via <code>BeamDappConnector.subscribe(&#39;ev_system_state&#39;, …)</code> and drop the 30 s timers; the API doesn&#39;t need to change.</p>\n<h2 id=\"api-response-time-targets\">Response-time targets</h2>\n<p>Measured against a 4-core / 8 GB VPS with ~50 k trades indexed:</p>\n<table>\n<thead>\n<tr>\n<th>Endpoint</th>\n<th>p50</th>\n<th>p95</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>/api/health</code></td>\n<td>&lt;5 ms</td>\n<td>20 ms</td>\n</tr>\n<tr>\n<td><code>/api/stats</code></td>\n<td>20 ms</td>\n<td>80 ms</td>\n</tr>\n<tr>\n<td><code>/api/pairs</code></td>\n<td>40 ms</td>\n<td>180 ms</td>\n</tr>\n<tr>\n<td><code>/api/pairs/{id}</code></td>\n<td>20 ms</td>\n<td>100 ms</td>\n</tr>\n<tr>\n<td><code>/api/pairs/{id}/ohlcv</code></td>\n<td>25 ms</td>\n<td>120 ms</td>\n</tr>\n<tr>\n<td><code>/api/pairs/{id}/trades</code></td>\n<td>15 ms</td>\n<td>80 ms</td>\n</tr>\n<tr>\n<td><code>/api/asset/{aid}/history</code> (cold)</td>\n<td>200 ms</td>\n<td>1 s (cached: &lt;10 ms)</td>\n</tr>\n</tbody></table>\n<p><code>/api/asset/{aid}/history</code> is the outlier because it round-trips to the explorer; the 5-minute LRU keeps the hit rate high in practice.</p>\n<h2 id=\"api-versioning\">Versioning</h2>\n<p>The endpoints documented here are mounted at <code>/api/*</code>. When we break shape, we&#39;ll add <code>/api/v2/*</code> alongside (the version segment isn&#39;t parsed today; it&#39;s a future affordance, not a current contract).</p>\n\n<hr>\n<h1>CoinGecko endpoints</h1>\n<h1>CoinGecko Integration</h1>\n<p>Public, no-auth endpoints we expose so CoinGecko can ingest BeamTerminal&#39;s DEX data.</p>\n<p>Spec source: CoinGecko Integration API Standards (the official internal Google doc, 2025 edition), <strong>Section A — Spot Exchanges API</strong>.</p>\n<p>BeamTerminal is a spot AMM DEX, so we serve:</p>\n<ul>\n<li><strong><code>GET /cg/tickers</code></strong> — mandatory. 24h pricing + volume for each pair.</li>\n<li><strong><code>GET /cg/historical_trades/{ticker_id}</code></strong> — optional but implemented. CG uses it for trade-history verification.</li>\n</ul>\n<p>We <strong>don&#39;t</strong> implement <code>/cg/orderbook/{ticker_id}</code> — AMMs aren&#39;t order books. We declare the depth formula on the submission form instead (constant product, per-tier fees). See <a href=\"#orderbook-policy\">§Orderbook policy</a>.</p>\n<p>Sections B (Derivatives), C (Circulating supply), and D (NFT) of the CG spec don&#39;t apply to BeamTerminal.</p>\n<h2 id=\"cg-general-requirements\">General requirements</h2>\n<table>\n<thead>\n<tr>\n<th>Requirement</th>\n<th>How we satisfy it</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Publicly accessible, no-auth</td>\n<td><code>/cg/*</code> is mounted authless on the same Fastify service as <code>/api/*</code>.</td>\n</tr>\n<tr>\n<td>Reasonable rate limits</td>\n<td>Per-IP, 600/min by default (configurable via <code>RATE_LIMIT_PER_MIN</code>).</td>\n</tr>\n<tr>\n<td>JSON format</td>\n<td>Default. <code>Content-Type: application/json</code>.</td>\n</tr>\n<tr>\n<td>User-Agent / IP allowlist</td>\n<td>None — the API is open. If we ever sit behind Cloudflare WAF, allow <code>User-Agent: CoinGecko +https://coingecko.com/</code> and <code>X-Requested-With: com.coingecko</code>.</td>\n</tr>\n<tr>\n<td>Website data matches API data</td>\n<td>The same Postgres rows feed <code>/api/*</code> (UI) and <code>/cg/*</code>. The UI displays last_price, 24h volume in USD, etc. on <code>/pair/:pairId</code>. Match is by construction.</td>\n</tr>\n</tbody></table>\n<h2 id=\"cg-pair-identity-mapping-beam-cg\">Pair identity mapping (BEAM → CG)</h2>\n<p>The CG spec is centered on EVM contract addresses. BEAM uses integer Asset IDs (AIDs). We emit the AID directly as the &quot;address&quot;:</p>\n<table>\n<thead>\n<tr>\n<th>CG field</th>\n<th>BeamTerminal value</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>ticker_id</code></td>\n<td><code>&quot;&lt;aid1&gt;_&lt;aid2&gt;_&lt;kind&gt;&quot;</code>, e.g. <code>&quot;0_31_1&quot;</code> for BEAM/USDT Medium tier. Underscore delimiter per CG spec.</td>\n</tr>\n<tr>\n<td><code>base_currency</code></td>\n<td>The base asset&#39;s AID as a decimal string, e.g. <code>&quot;0&quot;</code> for BEAM.</td>\n</tr>\n<tr>\n<td><code>target_currency</code></td>\n<td>The target asset&#39;s AID as a decimal string, e.g. <code>&quot;31&quot;</code> for USDT.</td>\n</tr>\n<tr>\n<td><code>pool_id</code></td>\n<td>The pool&#39;s <strong>LP token AID</strong> (<code>pools.aid_ctl</code>) as a decimal string. Every pool has a unique LP token, so this is BEAM&#39;s natural per-pool identifier — analogous to a pool contract address on EVM chains.</td>\n</tr>\n</tbody></table>\n<p>Numeric fields are emitted as decimal strings (no scientific notation, no trailing zeros below meaningful precision) via a single <code>toDecimal()</code> helper, so the wire format never leaks JS&#39;s number formatting quirks. BEAM assets are 8-decimal natively; CG amounts are in <strong>whole units</strong> (groths divided by <code>10^decimals</code>).</p>\n<h2 id=\"cg-endpoint-1-get-cg-tickers\">Endpoint 1 — <code>GET /cg/tickers</code></h2>\n<p>24h pricing + volume per pair. One row per non-imposter, non-destroyed pool. Sorted by <code>pool_id</code> for deterministic output.</p>\n<p>Response: top-level JSON array.</p>\n<pre><code class=\"language-json\">[\n  {\n    &quot;ticker_id&quot;:        &quot;0_31_1&quot;,\n    &quot;base_currency&quot;:    &quot;0&quot;,\n    &quot;target_currency&quot;:  &quot;31&quot;,\n    &quot;pool_id&quot;:          &quot;12345&quot;,\n    &quot;last_price&quot;:       &quot;29.34293421&quot;,\n    &quot;base_volume&quot;:      &quot;12000.5&quot;,\n    &quot;target_volume&quot;:    &quot;351923.403287&quot;,\n    &quot;liquidity_in_usd&quot;: &quot;7613.10&quot;,\n    &quot;bid&quot;:              &quot;29.3&quot;,\n    &quot;ask&quot;:              &quot;29.38&quot;,\n    &quot;high&quot;:             &quot;29.84&quot;,\n    &quot;low&quot;:              &quot;28.91&quot;\n  }\n]\n</code></pre>\n<h3 id=\"cg-per-field-semantics\">Per-field semantics</h3>\n<table>\n<thead>\n<tr>\n<th>Field</th>\n<th>Source</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>ticker_id</code></td>\n<td><code>pools.aid1 + &quot;_&quot; + aid2 + &quot;_&quot; + kind</code></td>\n<td>Stable per pool.</td>\n</tr>\n<tr>\n<td><code>base_currency</code></td>\n<td><code>pools.aid1</code> as decimal string.</td>\n<td></td>\n</tr>\n<tr>\n<td><code>target_currency</code></td>\n<td><code>pools.aid2</code> as decimal string.</td>\n<td></td>\n</tr>\n<tr>\n<td><code>pool_id</code></td>\n<td><code>pools.aid_ctl</code> (LP token AID) as decimal string.</td>\n<td>One LP token per pool; unique and stable.</td>\n</tr>\n<tr>\n<td><code>last_price</code></td>\n<td>Most recent confirmed <code>trades.price_native</code> (aid2 per aid1).</td>\n<td>Falls back to <code>reserve2 / reserve1</code> if no trade has happened on this pool.</td>\n</tr>\n<tr>\n<td><code>base_volume</code></td>\n<td>Sum of <code>trades.volume_aid1</code> over the last 24h, in whole <code>aid1</code> units. Confirmed trades only.</td>\n<td></td>\n</tr>\n<tr>\n<td><code>target_volume</code></td>\n<td>Same for <code>aid2</code>.</td>\n<td></td>\n</tr>\n<tr>\n<td><code>liquidity_in_usd</code></td>\n<td><code>reserve1_usd + reserve2_usd</code> at the latest snapshot, where each side&#39;s USD value comes from the BEAM-routed valuation table.</td>\n<td>When neither side is BEAM, we still get USD per side as long as both AIDs are reachable through <em>some</em> BEAM-quoted pool.</td>\n</tr>\n<tr>\n<td><code>bid</code></td>\n<td>AMM swap-out price for buying 1 whole unit of base via the curve, post-fee: <code>dy = r2·1/(r1+1) · (1 − fee)</code>.</td>\n<td>Required by CG for depth math.</td>\n</tr>\n<tr>\n<td><code>ask</code></td>\n<td>Same but reverse direction: <code>dx = r2/(r1−1) / (1 − fee)</code>.</td>\n<td></td>\n</tr>\n<tr>\n<td><code>high</code> / <code>low</code></td>\n<td><code>MAX(price_native)</code> / <code>MIN(price_native)</code> over the last 24h of confirmed trades. Falls back to <code>last_price</code> if no trades in window.</td>\n<td></td>\n</tr>\n</tbody></table>\n<h3 id=\"cg-pools-we-omit\">Pools we omit</h3>\n<ul>\n<li><code>pools.destroyed_at_height IS NOT NULL</code> — destroyed pools.</li>\n<li>Either side <code>assets.is_imposter = TRUE</code> — imposter pools.</li>\n<li>Zero liquidity AND zero 24h volume — keeps the catalog tight per CG&#39;s &quot;no dead markets&quot; guidance.</li>\n</ul>\n<p>The first two filters live in SQL; the third is applied at row-build time. Imposter pools remain visible (with a warning badge) in <code>/api/*</code> but are completely hidden from <code>/cg/*</code>.</p>\n<p><code>Cache-Control: public, max-age=30</code>.</p>\n<h2 id=\"cg-endpoint-2-get-cg-historical-trades-ticker-id\">Endpoint 2 — <code>GET /cg/historical_trades/{ticker_id}</code></h2>\n<p>Trade history for a single pair, split by side per the CG spec.</p>\n<p><code>ticker_id</code> format: <code>&quot;&lt;aid1&gt;_&lt;aid2&gt;_&lt;kind&gt;&quot;</code>. 400 (<code>BAD_TICKER_ID</code>) on bad shape; 404 (<code>PAIR_NOT_FOUND</code>) when no active non-imposter pool matches.</p>\n<p>Query params:</p>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Default</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>type</code></td>\n<td><code>&quot;buy&quot;</code> | <code>&quot;sell&quot;</code></td>\n<td>—</td>\n<td>If omitted, returns both.</td>\n</tr>\n<tr>\n<td><code>limit</code></td>\n<td>int, 0..500</td>\n<td>100</td>\n<td><code>0</code> means &quot;full history&quot; (capped at 5000 for safety).</td>\n</tr>\n<tr>\n<td><code>start_time</code></td>\n<td>unix seconds</td>\n<td>—</td>\n<td>Inclusive.</td>\n</tr>\n<tr>\n<td><code>end_time</code></td>\n<td>unix seconds</td>\n<td>—</td>\n<td>Inclusive.</td>\n</tr>\n</tbody></table>\n<p>Response:</p>\n<pre><code class=\"language-json\">{\n  &quot;buy&quot;: [\n    {\n      &quot;trade_id&quot;:        81729,\n      &quot;price&quot;:           &quot;29.34293421&quot;,\n      &quot;base_volume&quot;:     &quot;10&quot;,\n      &quot;target_volume&quot;:   &quot;293.4293421&quot;,\n      &quot;trade_timestamp&quot;: 1747400940,\n      &quot;type&quot;:            &quot;buy&quot;\n    }\n  ],\n  &quot;sell&quot;: [\n    {\n      &quot;trade_id&quot;:        81728,\n      &quot;price&quot;:           &quot;29.33102233&quot;,\n      &quot;base_volume&quot;:     &quot;5&quot;,\n      &quot;target_volume&quot;:   &quot;146.65511165&quot;,\n      &quot;trade_timestamp&quot;: 1747400600,\n      &quot;type&quot;:            &quot;sell&quot;\n    }\n  ]\n}\n</code></pre>\n<h3 id=\"cg-per-field-semantics-x\">Per-field semantics</h3>\n<table>\n<thead>\n<tr>\n<th>Field</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>trade_id</code></td>\n<td><code>trades.trade_id</code>. Integer, unique within our DB. CG spec is explicit that <code>trade_id</code> must not be a unix timestamp; an integer is fine.</td>\n</tr>\n<tr>\n<td><code>price</code></td>\n<td><code>trades.price_native</code> (aid2 per aid1), decimal string.</td>\n</tr>\n<tr>\n<td><code>base_volume</code></td>\n<td><code>volume_aid1</code> in whole units (<code>/ 10^decimals1</code>), decimal string.</td>\n</tr>\n<tr>\n<td><code>target_volume</code></td>\n<td><code>volume_aid2</code> in whole units, decimal string.</td>\n</tr>\n<tr>\n<td><code>trade_timestamp</code></td>\n<td>Unix <strong>seconds</strong> (per CG spec).</td>\n</tr>\n<tr>\n<td><code>type</code></td>\n<td><code>&quot;buy&quot;</code> if <code>aid_in == pools.aid2</code> — the user paid the target to acquire the base, matching the AMM contract&#39;s <code>m_Buy1</code> (= buy aid1); <code>&quot;sell&quot;</code> otherwise.</td>\n</tr>\n</tbody></table>\n<p>Filters:</p>\n<ul>\n<li><code>confirmed = TRUE</code> only.</li>\n<li>Imposter / destroyed pairs respond 404 rather than empty.</li>\n<li>Default ordering: <code>trade_timestamp DESC</code>.</li>\n</ul>\n<p><code>Cache-Control: public, max-age=15</code>.</p>\n<h2 id=\"cg-orderbook-policy\">Orderbook policy</h2>\n<p>AMM ≠ orderbook. Per CG spec:</p>\n<blockquote>\n<p>If the formula is not provided, we will apply the Uniswap V2 formula to derive depth.</p>\n</blockquote>\n<p>BEAM AMM is a vanilla constant-product market maker (<code>x · y = k</code>), identical math to Uniswap V2. We declare on the CG submission form:</p>\n<blockquote>\n<p>Depth formula: constant product (Uniswap V2). Per-tier fees added to the input side: 0.05% (Low), 0.30% (Medium), 1.00% (High).</p>\n</blockquote>\n<p>CG&#39;s default Uniswap-V2 depth derivation works as-is. If CG ever asks for an explicit endpoint we&#39;d add it as <code>/cg/orderbook/{ticker_id}</code> synthesizing levels by walking the curve in fixed price steps — but until then it&#39;s deliberately absent.</p>\n<h2 id=\"cg-what-cg-verifies-on-submission\">What CG verifies on submission</h2>\n<p>Per the spec:</p>\n<blockquote>\n<p>In order for us to verify the data returned in your provided API endpoints, it is mandatory to display important information (e.g. last price, 24h volume (in USD), open interest, funding rate, etc.) on your trading page/web interface. Your request will be rejected if the data in your API endpoints does not match with what is shown on your website.</p>\n</blockquote>\n<p>Source of truth for verification is <code>/pair/:pairId</code> in the React app:</p>\n<table>\n<thead>\n<tr>\n<th><code>/cg/tickers</code> field</th>\n<th>Visible on <code>/pair/:pairId</code> as</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>last_price</code></td>\n<td>The &quot;Price&quot; value in the sidebar.</td>\n</tr>\n<tr>\n<td><code>base_volume</code> / <code>target_volume</code></td>\n<td>Volume row in sidebar (USD equivalent shown alongside).</td>\n</tr>\n<tr>\n<td><code>liquidity_in_usd</code></td>\n<td>Liquidity row in sidebar; per-side breakdown in &quot;Pooled Tokens&quot;.</td>\n</tr>\n<tr>\n<td><code>bid</code> / <code>ask</code></td>\n<td>Implicit in the swap panel quote (uses the same AMM curve math).</td>\n</tr>\n<tr>\n<td><code>high</code> / <code>low</code></td>\n<td>Chart&#39;s 24h range (visible via crosshair OHLC legend or the chart&#39;s price-scale extremes).</td>\n</tr>\n</tbody></table>\n<h2 id=\"cg-submission-checklist\">Submission checklist</h2>\n<p>When applying via the CG application form:</p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> <code>/cg/tickers</code> deployed, returns ≥1 ticker.</li>\n<li><input disabled=\"\" type=\"checkbox\"> <code>/cg/historical_trades/{ticker_id}</code> deployed, returns recent trades for that ticker.</li>\n<li><input disabled=\"\" type=\"checkbox\"> Depth formula declared in the submission form: constant product, per-tier fees <code>0.05% / 0.30% / 1.00%</code>.</li>\n<li><input disabled=\"\" type=\"checkbox\"> Numeric fields shown in <code>/pair/:pairId</code> UI match endpoint data.</li>\n<li><input disabled=\"\" type=\"checkbox\"> Endpoints reachable over HTTPS, no auth, no Cloudflare bot challenge.</li>\n<li><input disabled=\"\" type=\"checkbox\"> Submission note explicitly states: <code>base_currency</code> / <code>target_currency</code> are BEAM Asset IDs (decimal); <code>pool_id</code> is the LP token&#39;s AID.</li>\n</ul>\n<h2 id=\"cg-implementation-notes\">Implementation notes</h2>\n<ul>\n<li><code>/cg/*</code> handlers live in the same Fastify service as <code>/api/*</code> (<code>backend/src/api/routes/cg/</code>).</li>\n<li>Imposter / destroyed / zero-liquidity filters are applied in the CG handlers, not via a shared SQL view — keeps the differences visible. We accept that the two surfaces have intentionally different row sets.</li>\n<li>Numeric formatting goes through a <code>toDecimal(value, maxFractionDigits)</code> helper so we never accidentally emit scientific notation.</li>\n<li><code>trades.price_native</code> and <code>trades.volume_aid1</code> / <code>volume_aid2</code> are pre-computed at insert time (see <a href=\"database.md#trades--hypertable\">database.md §trades</a>), so the CG endpoints don&#39;t need joins against <code>pools</code> on the hot path.</li>\n</ul>\n<h2 id=\"cg-reference-implementations-cited-by-the-spec\">Reference implementations cited by the spec</h2>\n<p>Useful for cross-checking shape — both DEX examples:</p>\n<ul>\n<li><code>https://api.hyperliquid.xyz/aggregator/v1/spot/tickers</code></li>\n<li><code>https://api.cellana.finance/api/v1/tool/tickers</code></li>\n</ul>\n<p>Our shape mirrors these, with the BEAM-specific AID namespace.</p>\n\n</main></div>\n<footer class=\"site-footer\"><div class=\"site-footer-inner\">\n<div><div class=\"fcol-title\">BEAM</div><a href=\"https://beam.mw\" target=\"_blank\" rel=\"noopener noreferrer\">beam.mw</a></div>\n<div><div class=\"fcol-title\">Community</div><a href=\"https://x.com/beamprivacy\" target=\"_blank\" rel=\"noopener noreferrer\">X (Twitter)</a><a href=\"https://t.me/beamprivacy\" target=\"_blank\" rel=\"noopener noreferrer\">Telegram</a><a href=\"https://discord.gg/fwfArUqpfh\" target=\"_blank\" rel=\"noopener noreferrer\">Discord</a></div>\n<div><div class=\"fcol-title\">BeamTerminal</div><a href=\"https://github.com/Maxnflaxl/BeamTerminal\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub</a><a href=\"https://beamterminal.0xmx.net/api/\">API</a><a href=\"https://beamterminal.0xmx.net/#/privacy\" target=\"_blank\" rel=\"noopener noreferrer\">Privacy Policy</a></div>\n<div><div class=\"fcol-title\">Contact</div><a href=\"mailto:me@maxnflaxl.dev\">me@maxnflaxl.dev</a><a href=\"https://t.me/maxnflaxl\" target=\"_blank\" rel=\"noopener noreferrer\">Telegram (@maxnflaxl)</a></div>\n</div></footer>\n</body></html>";
